\documentclass{article}
\usepackage{pgfplots}
\usepackage{amsmath}
\pagestyle{empty}

\begin{document}

\begin{tikzpicture}[scale=1]
    	\begin{axis}[  	
                	tick label style={font=\footnotesize},
                    	label style={font=\small},,
                    	tick style={line width=0.8pt, color=black},
                    	axis line style = thick,
                    	axis y line = center,
                    	axis x line = middle,
                    	%axis equal,
                    	%grid = both,
                    	xmin = -1,
                    	xmax = 2,
                    	ymin = -4,
                    	ymax = 4,
                    	xtick = {0},
                    	ytick = {0},  
                    	xlabel = $x$,
                    	ylabel = {$y$},
                    	xlabel style={below},
                    	ylabel style={right},
                    	every axis x label/.style={
                    		at={(ticklabel* cs:1.02)},
                    		anchor=west,
                    	},
                    	every axis y label/.style={
                    		at={(ticklabel* cs:1.02)},
                    		anchor=south,
                    	}
                	]

        	\addplot [
        	domain=-3:3,
        	samples=100,
        	color=red,
        	line width=1pt,
        	]{3*x^4-x^3+4*x^2-7*x};

        \end{axis}

\end{tikzpicture}
\end{document}

